INSERT INTO `SYSTEM_CONFIG` (`CLUB_ID`, `CONFIG_KEY`, `CONFIG_VALUE`, `VALUE_TYPE`, `DESCRIPTION`, `UPDATED_AT`) VALUES (1,'AI_MAX_OUTPUT_TOKENS','2000','INT','AI 답변 최대 길이(토큰). 넘으면 잘려서 다시 쓰고, 그래도 안 되면 기본형 기사','2026-06-28 12:00:00.000'),(1,'AI_TEMPERATURE','0.7','FLOAT','AI 기사 창의성(temperature, 0~2). 낮을수록 사실 위주로 일정, 높을수록 표현이 다양','2026-06-28 12:00:00.000'),(1,'ARTICLE_PUBLISH_MODE','MANUAL','STRING','기사 게시 방식: MANUAL=관리자 검토 후 게시, AUTO=생성 즉시 게시','2026-06-28 12:00:00.000'),(1,'CONFIDENCE_DECAY_DAYS','90.0','FLOAT','미출전 Confidence 감쇠 시간상수(일)','2026-06-28 12:00:00.000'),(1,'CONFIDENCE_DECAY_GRACE_DAYS','30','INT','미출전 후 Confidence 감소가 시작되는 일수','2026-06-28 12:00:00.000'),(1,'CONFIDENCE_MATCH_SCALE','10.0','FLOAT','경기 수에 따른 Confidence 상승 속도(클수록 느림)','2026-06-28 12:00:00.000'),(1,'CONFIDENCE_MULT_MAX','2.0','FLOAT','Confidence 0일 때 Rating 변화 배수','2026-06-28 12:00:00.000'),(1,'CONFIDENCE_MULT_MIN','0.5','FLOAT','Confidence 1일 때 Rating 변화 배수','2026-06-28 12:00:00.000'),(1,'HEADCOUNT_ADVANTAGE_FACTOR','0.0','FLOAT','팀 인원 1명당 Team Strength 가산(초기 0)','2026-06-28 12:00:00.000'),(1,'INITIAL_RATING','1000.0','FLOAT','신규 선수 초기 Rating','2026-06-28 12:00:00.000'),(1,'MATCH_AUTO_END_YN','TRUE','BOOL','시간 종료 시 자동 종료 여부(관리자 END는 항상 가능)','2026-06-28 12:00:00.000'),(1,'MATCH_DURATION_SEC','600','INT','경기 시간(초)','2026-06-28 12:00:00.000'),(1,'MATCH_EARLY_END_GOALS','0','INT','한 팀이 N골에 도달하면 조기 종료(0=사용 안 함)','2026-06-28 12:00:00.000'),(1,'MATCH_RATING_K','20.0','FLOAT','경기 결과 Rating 변화 K','2026-06-28 12:00:00.000'),(1,'MONTHLY_MVP_MIN_SESSIONS','2','INT','이달의 MVP 후보 자격: 그 달 출전한 일정 수(이상)','2026-06-28 12:00:00.000'),(1,'PAIR_ALPHA','2.0','FLOAT','Pair Penalty smoothing alpha','2026-06-28 12:00:00.000'),(1,'PAIR_PENALTY_EPSILON','0.01','FLOAT','Pair Penalty가 이 차이 이내면 동점으로 보고 Rating 균형 비교','2026-06-28 12:00:00.000'),(1,'RATING_EXPECTATION_SCALE','400.0','FLOAT','Elo 기대승률 scale','2026-06-28 12:00:00.000'),(1,'TEAM_CANDIDATE_COUNT','3000','INT','팀 편성 후보 생성 수','2026-06-28 12:00:00.000'),(1,'TEAM_RATING_TOLERANCE_PERCENT','1.0','FLOAT','팀 Strength 허용 차이(%) = (최고-최저)/평균','2026-06-28 12:00:00.000'),(1,'WIRE_MAX_INSIGHTS','15','INT','기사 1건에 AI로 넘기는 Insight 최대 개수','2026-06-28 12:00:00.000');
