INSERT INTO `AI_ARTICLE` (`ARTICLE_ID`, `CLUB_ID`, `SESSION_ID`, `MATCH_ID`, `ARTICLE_TYPE`, `TITLE`, `SUMMARY`, `CONTENT`, `MODEL_NAME`, `PROMPT_VERSION`, `INSIGHT_RULE_VERSION`, `STATUS`, `PUBLISHED_YN`, `PUBLISHED_AT`, `PARENT_ARTICLE_ID`, `GENERATION_NO`, `REQUEST_JSON`, `RESPONSE_JSON`, `ERROR_MESSAGE`, `UPDATED_AT`, `CREATED_AT`) VALUES (1,1,1,NULL,'PRE_MATCH','7월 4일, YPR 기록의 첫 페이지','7월 4일 토요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.','7월 4일 토요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.\n\nA팀은 권태홍, 김병채, 김재홍 등 7명, B팀은 김동근, 변현우, 안휘진 등 6명, C팀은 구대현, 김응철, 이민선 등 6명으로 꾸려졌다.\n\n경기 결과와 오늘의 주인공은 마감 기사에서 전한다.','sample-template','wire_prompt_v4','FIRST_APPEARANCE:first_appearance_v1','PUBLISHED',1,'2026-07-03 22:46:00.000',NULL,1,'{\"teams\": [{\"members\": [\"권태홍\", \"김병채\", \"김재홍\", \"김현섭\", \"손원일\", \"윤영문\", \"전원재\"], \"teamCode\": \"A\", \"guestCount\": 0}, {\"members\": [\"김동근\", \"변현우\", \"안휘진\", \"윤기창\", \"이채현\", \"임우철\"], \"teamCode\": \"B\", \"guestCount\": 0}, {\"members\": [\"구대현\", \"김응철\", \"이민선\", \"이용준\", \"이종훈\", \"진선호\"], \"teamCode\": \"C\", \"guestCount\": 0}], \"clubName\": \"YPR\", \"insights\": [{\"id\": 1, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"손원일\", \"memberId\": 1}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"손원일\", \"memberId\": 1}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 2, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김응철\", \"memberId\": 2}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김응철\", \"memberId\": 2}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 3, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"안휘진\", \"memberId\": 3}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"안휘진\", \"memberId\": 3}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 4, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"전원재\", \"memberId\": 5}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"전원재\", \"memberId\": 5}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 5, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김현섭\", \"memberId\": 6}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김현섭\", \"memberId\": 6}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 6, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"윤기창\", \"memberId\": 7}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"윤기창\", \"memberId\": 7}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 7, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"이종훈\", \"memberId\": 8}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"이종훈\", \"memberId\": 8}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 8, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"이용준\", \"memberId\": 11}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"이용준\", \"memberId\": 11}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 9, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"변현우\", \"memberId\": 12}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"변현우\", \"memberId\": 12}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 10, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김재홍\", \"memberId\": 13}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김재홍\", \"memberId\": 13}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 11, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김동근\", \"memberId\": 14}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김동근\", \"memberId\": 14}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 12, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"이민선\", \"memberId\": 15}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"이민선\", \"memberId\": 15}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 13, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"권태홍\", \"memberId\": 16}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"권태홍\", \"memberId\": 16}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 14, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"진선호\", \"memberId\": 17}, \"teamCode\": \"C\", \"firstAppearance\": true}, \"subject\": {\"name\": \"진선호\", \"memberId\": 17}, \"category\": \"PLAYER\", \"importance\": 50}, {\"id\": 15, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"임우철\", \"memberId\": 18}, \"teamCode\": \"B\", \"firstAppearance\": true}, \"subject\": {\"name\": \"임우철\", \"memberId\": 18}, \"category\": \"PLAYER\", \"importance\": 50}], \"location\": null, \"articleType\": \"PRE_MATCH\", \"sessionDate\": \"2026-07-04\", \"sessionTitle\": \"토요 정기 경기\"}','{\"body\": \"7월 4일 토요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.\\n\\nA팀은 권태홍, 김병채, 김재홍 등 7명, B팀은 김동근, 변현우, 안휘진 등 6명, C팀은 구대현, 김응철, 이민선 등 6명으로 꾸려졌다.\\n\\n경기 결과와 오늘의 주인공은 마감 기사에서 전한다.\", \"title\": \"7월 4일, YPR 기록의 첫 페이지\", \"summary\": \"7월 4일 토요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 오늘부터 모든 경기 기록이 쌓이기 시작한다.\", \"usedInsightIds\": []}',NULL,'2026-07-03 22:46:00.000','2026-07-03 22:40:00.000'),(2,1,1,NULL,'SESSION_RECAP','김현섭, 종료 47초 전 결승골','6경기는 김현섭의 발끝에서 갈렸다. 종료 47초를 남기고 터진 결승골이었다.','7월 4일 YPR은 9경기를 치르며 총 36골을 기록했다. B팀이 2승 3무 1패로 가장 많은 승리를 챙겼다.\n\n득점 순위에서는 안휘진(5골), 전원재(4골), 김동근(3골) 순으로 앞섰다.\n\n6경기는 김현섭의 발끝에서 갈렸다. 종료 47초를 남기고 터진 결승골이었다. 권태홍의 패스를 전원재가 마무리한 골이 오늘만 세 번 나왔다.\n\n안휘진의 패스를 김동근이 마무리한 골이 오늘만 두 번 나왔다. 윤기창의 패스를 안휘진이 마무리한 골이 오늘만 두 번 나왔다.\n\n안휘진이 이주의 득점왕(5골)에 이름을 올렸다. 권태홍이 이주의 도움왕(5도움)에 이름을 올렸다.\n\n1경기  A 3 : 3 B\n2경기  B 0 : 2 C\n3경기  C 2 : 2 A\n4경기  A 2 : 2 B\n5경기  B 3 : 1 C\n6경기  C 3 : 4 A\n7경기  A 2 : 2 B\n8경기  B 2 : 0 C\n9경기  C 2 : 1 A','sample-template','wire_prompt_v4','ASSIST_COMBO:assist_combo_v1,LATE_WINNER:late_winner_v1,TITLE_AWARDED:title_awarded_v1','PUBLISHED',1,'2026-07-04 01:48:00.000',NULL,1,'{\"clubName\": \"YPR\", \"insights\": [{\"id\": 20, \"type\": \"LATE_WINNER\", \"facts\": {\"teamA\": \"C\", \"teamB\": \"A\", \"assist\": {\"name\": \"권태홍\", \"memberId\": 16}, \"gameNo\": 6, \"member\": {\"name\": \"김현섭\", \"memberId\": 6}, \"scoreA\": 3, \"scoreB\": 4, \"winnerTeam\": \"A\", \"remainingSec\": 47, \"inStoppageTime\": false}, \"subject\": {\"name\": \"김현섭\", \"memberId\": 6}, \"category\": \"MATCH\", \"importance\": 68}, {\"id\": 21, \"type\": \"ASSIST_COMBO\", \"facts\": {\"member\": {\"name\": \"전원재\", \"memberId\": 5}, \"scorer\": {\"name\": \"전원재\", \"memberId\": 5}, \"assister\": {\"name\": \"권태홍\", \"memberId\": 16}, \"countToday\": 3, \"careerCount\": 3}, \"subject\": {\"name\": \"전원재\", \"memberId\": 5}, \"category\": \"PAIR\", \"importance\": 60}, {\"id\": 22, \"type\": \"ASSIST_COMBO\", \"facts\": {\"member\": {\"name\": \"김동근\", \"memberId\": 14}, \"scorer\": {\"name\": \"김동근\", \"memberId\": 14}, \"assister\": {\"name\": \"안휘진\", \"memberId\": 3}, \"countToday\": 2, \"careerCount\": 2}, \"subject\": {\"name\": \"김동근\", \"memberId\": 14}, \"category\": \"PAIR\", \"importance\": 50}, {\"id\": 23, \"type\": \"ASSIST_COMBO\", \"facts\": {\"member\": {\"name\": \"안휘진\", \"memberId\": 3}, \"scorer\": {\"name\": \"안휘진\", \"memberId\": 3}, \"assister\": {\"name\": \"윤기창\", \"memberId\": 7}, \"countToday\": 2, \"careerCount\": 2}, \"subject\": {\"name\": \"안휘진\", \"memberId\": 3}, \"category\": \"PAIR\", \"importance\": 50}, {\"id\": 24, \"type\": \"TITLE_AWARDED\", \"facts\": {\"tied\": false, \"value\": 5, \"member\": {\"name\": \"안휘진\", \"memberId\": 3}, \"metric\": \"goals\", \"periodEnd\": \"2026-07-05\", \"titleName\": \"이주의 득점왕\", \"periodStart\": \"2026-06-29\"}, \"subject\": {\"name\": \"안휘진\", \"memberId\": 3}, \"category\": \"TITLE\", \"importance\": 50}, {\"id\": 25, \"type\": \"TITLE_AWARDED\", \"facts\": {\"tied\": false, \"value\": 5, \"member\": {\"name\": \"권태홍\", \"memberId\": 16}, \"metric\": \"assists\", \"periodEnd\": \"2026-07-05\", \"titleName\": \"이주의 도움왕\", \"periodStart\": \"2026-06-29\"}, \"subject\": {\"name\": \"권태홍\", \"memberId\": 16}, \"category\": \"TITLE\", \"importance\": 50}], \"location\": null, \"articleType\": \"SESSION_RECAP\", \"sessionDate\": \"2026-07-04\", \"sessionTitle\": \"토요 정기 경기\", \"sessionSummary\": {\"matches\": [{\"teamA\": \"A\", \"teamB\": \"B\", \"gameNo\": 1, \"scoreA\": 3, \"scoreB\": 3, \"winner\": null}, {\"teamA\": \"B\", \"teamB\": \"C\", \"gameNo\": 2, \"scoreA\": 0, \"scoreB\": 2, \"winner\": \"C\"}, {\"teamA\": \"C\", \"teamB\": \"A\", \"gameNo\": 3, \"scoreA\": 2, \"scoreB\": 2, \"winner\": null}, {\"teamA\": \"A\", \"teamB\": \"B\", \"gameNo\": 4, \"scoreA\": 2, \"scoreB\": 2, \"winner\": null}, {\"teamA\": \"B\", \"teamB\": \"C\", \"gameNo\": 5, \"scoreA\": 3, \"scoreB\": 1, \"winner\": \"B\"}, {\"teamA\": \"C\", \"teamB\": \"A\", \"gameNo\": 6, \"scoreA\": 3, \"scoreB\": 4, \"winner\": \"A\"}, {\"teamA\": \"A\", \"teamB\": \"B\", \"gameNo\": 7, \"scoreA\": 2, \"scoreB\": 2, \"winner\": null}, {\"teamA\": \"B\", \"teamB\": \"C\", \"gameNo\": 8, \"scoreA\": 2, \"scoreB\": 0, \"winner\": \"B\"}, {\"teamA\": \"C\", \"teamB\": \"A\", \"gameNo\": 9, \"scoreA\": 2, \"scoreB\": 1, \"winner\": \"C\"}], \"topScorers\": [{\"name\": \"안휘진\", \"goals\": 5}, {\"name\": \"전원재\", \"goals\": 4}, {\"name\": \"김동근\", \"goals\": 3}, {\"name\": \"김병채\", \"goals\": 2}, {\"name\": \"김현섭\", \"goals\": 2}], \"teamRecords\": {\"A\": {\"wins\": 1, \"draws\": 4, \"losses\": 1}, \"B\": {\"wins\": 2, \"draws\": 3, \"losses\": 1}, \"C\": {\"wins\": 2, \"draws\": 1, \"losses\": 3}}, \"totalMatches\": 9}}','{\"body\": \"7월 4일 YPR은 9경기를 치르며 총 36골을 기록했다. B팀이 2승 3무 1패로 가장 많은 승리를 챙겼다.\\n\\n득점 순위에서는 안휘진(5골), 전원재(4골), 김동근(3골) 순으로 앞섰다.\\n\\n6경기는 김현섭의 발끝에서 갈렸다. 종료 47초를 남기고 터진 결승골이었다. 권태홍의 패스를 전원재가 마무리한 골이 오늘만 세 번 나왔다.\\n\\n안휘진의 패스를 김동근이 마무리한 골이 오늘만 두 번 나왔다. 윤기창의 패스를 안휘진이 마무리한 골이 오늘만 두 번 나왔다.\\n\\n안휘진이 이주의 득점왕(5골)에 이름을 올렸다. 권태홍이 이주의 도움왕(5도움)에 이름을 올렸다.\\n\\n1경기  A 3 : 3 B\\n2경기  B 0 : 2 C\\n3경기  C 2 : 2 A\\n4경기  A 2 : 2 B\\n5경기  B 3 : 1 C\\n6경기  C 3 : 4 A\\n7경기  A 2 : 2 B\\n8경기  B 2 : 0 C\\n9경기  C 2 : 1 A\", \"title\": \"김현섭, 종료 47초 전 결승골\", \"summary\": \"6경기는 김현섭의 발끝에서 갈렸다. 종료 47초를 남기고 터진 결승골이었다.\", \"usedInsightIds\": [20, 21, 22, 23, 24, 25]}',NULL,'2026-07-04 01:48:00.000','2026-07-04 01:25:00.000'),(3,1,2,NULL,'PRE_MATCH','오늘은 접전 예고','팀 간 전력이 고르게 나뉘어 어느 팀도 쉽게 승리를 장담하기 어렵다.','7월 11일 토요일, YPR 17명이 3개 팀으로 나뉘어 맞붙는다.\n\nA팀은 김승준, 김재홍, 안휘진 등 6명, B팀은 구대현, 김병채, 김응철 등 6명, C팀은 김동근, 김현섭, 변현우 등 5명으로 꾸려졌다.\n\n팀 간 전력이 고르게 나뉘어 어느 팀도 쉽게 승리를 장담하기 어렵다. 김승준은 오늘이 기록 집계 후 첫 출전이다.\n\n첫 경기 휘슬과 함께 오늘의 이야기가 시작된다.','sample-template','wire_prompt_v4','CLOSE_MATCH_EXPECTED:close_match_expected_v1,FIRST_APPEARANCE:first_appearance_v1','PUBLISHED',1,'2026-07-10 22:46:00.000',NULL,1,'{\"teams\": [{\"members\": [\"김승준\", \"김재홍\", \"안휘진\", \"이민선\", \"이종훈\", \"임우철\"], \"teamCode\": \"A\", \"guestCount\": 0}, {\"members\": [\"구대현\", \"김병채\", \"김응철\", \"손원일\", \"윤기창\", \"이채현\"], \"teamCode\": \"B\", \"guestCount\": 0}, {\"members\": [\"김동근\", \"김현섭\", \"변현우\", \"윤영문\", \"이용준\"], \"teamCode\": \"C\", \"guestCount\": 0}], \"clubName\": \"YPR\", \"insights\": [{\"id\": 27, \"type\": \"CLOSE_MATCH_EXPECTED\", \"facts\": {\"balanced\": true, \"teamCodes\": [\"A\", \"B\", \"C\"]}, \"subject\": null, \"category\": \"MATCH\", \"importance\": 69}, {\"id\": 26, \"type\": \"FIRST_APPEARANCE\", \"facts\": {\"member\": {\"name\": \"김승준\", \"memberId\": 20}, \"teamCode\": \"A\", \"firstAppearance\": true}, \"subject\": {\"name\": \"김승준\", \"memberId\": 20}, \"category\": \"PLAYER\", \"importance\": 50}], \"location\": null, \"articleType\": \"PRE_MATCH\", \"sessionDate\": \"2026-07-11\", \"sessionTitle\": \"토요 정기 경기\"}','{\"body\": \"7월 11일 토요일, YPR 17명이 3개 팀으로 나뉘어 맞붙는다.\\n\\nA팀은 김승준, 김재홍, 안휘진 등 6명, B팀은 구대현, 김병채, 김응철 등 6명, C팀은 김동근, 김현섭, 변현우 등 5명으로 꾸려졌다.\\n\\n팀 간 전력이 고르게 나뉘어 어느 팀도 쉽게 승리를 장담하기 어렵다. 김승준은 오늘이 기록 집계 후 첫 출전이다.\\n\\n첫 경기 휘슬과 함께 오늘의 이야기가 시작된다.\", \"title\": \"오늘은 접전 예고\", \"summary\": \"팀 간 전력이 고르게 나뉘어 어느 팀도 쉽게 승리를 장담하기 어렵다.\", \"usedInsightIds\": [27, 26]}',NULL,'2026-07-10 22:46:00.000','2026-07-10 22:40:00.000');
INSERT INTO `AI_ARTICLE` (`ARTICLE_ID`, `CLUB_ID`, `SESSION_ID`, `MATCH_ID`, `ARTICLE_TYPE`, `TITLE`, `SUMMARY`, `CONTENT`, `MODEL_NAME`, `PROMPT_VERSION`, `INSIGHT_RULE_VERSION`, `STATUS`, `PUBLISHED_YN`, `PUBLISHED_AT`, `PARENT_ARTICLE_ID`, `GENERATION_NO`, `REQUEST_JSON`, `RESPONSE_JSON`, `ERROR_MESSAGE`, `UPDATED_AT`, `CREATED_AT`) VALUES (4,1,2,NULL,'SESSION_RECAP','손원일, 종료 13초 전 결승골','8경기는 손원일의 발끝에서 갈렸다. 종료 13초를 남기고 터진 결승골이었다.','7월 11일 YPR은 9경기를 치르며 총 21골을 기록했다. A팀이 3승 1무 2패로 가장 많은 승리를 챙겼다.\n\n득점 순위에서는 김응철(4골), 안휘진(3골), 김재홍(3골) 순으로 앞섰다.\n\n8경기는 손원일의 발끝에서 갈렸다. 종료 13초를 남기고 터진 결승골이었다. 손원일 등 14명이 통산 10경기 출전 고지를 밟았다.\n\n1경기  A 1 : 2 B\n2경기  B 0 : 1 C\n3경기  C 0 : 1 A\n4경기  A 0 : 2 B\n5경기  B 1 : 3 C\n6경기  C 0 : 2 A\n7경기  A 3 : 0 B\n8경기  B 2 : 1 C\n9경기  C 1 : 1 A','sample-template','wire_prompt_v4','CLEAN_SHEET:clean_sheet_v1,FIRST_ASSIST:first_assist_v1,FIRST_GOAL:first_goal_v1,LATE_WINNER:late_winner_v1,MILESTONE_ACHIEVED:milestone_achieved_v1,TITLE_AWARDED:title_awarded_v1','PUBLISHED',1,'2026-07-11 01:46:00.000',NULL,1,'{\"clubName\": \"YPR\", \"insights\": [{\"id\": 28, \"type\": \"LATE_WINNER\", \"facts\": {\"teamA\": \"B\", \"teamB\": \"C\", \"gameNo\": 8, \"member\": {\"name\": \"손원일\", \"memberId\": 1}, \"scoreA\": 2, \"scoreB\": 1, \"winnerTeam\": \"B\", \"remainingSec\": 13, \"inStoppageTime\": false}, \"subject\": {\"name\": \"손원일\", \"memberId\": 1}, \"category\": \"MATCH\", \"importance\": 87}, {\"id\": 29, \"type\": \"MILESTONE_ACHIEVED\", \"facts\": {\"total\": 12, \"member\": {\"name\": \"손원일\", \"memberId\": 1}, \"metric\": \"games\", \"milestone\": 10, \"metricLabel\": \"출전 경기\"}, \"subject\": {\"name\": \"손원일\", \"memberId\": 1}, \"category\": \"MILESTONE\", \"importance\": 55}, {\"id\": 30, \"type\": \"MILESTONE_ACHIEVED\", \"facts\": {\"total\": 12, \"member\": {\"name\": \"김응철\", \"memberId\": 2}, \"metric\": \"games\", \"milestone\": 10, \"metricLabel\": \"출전 경기\"}, \"subject\": {\"name\": \"김응철\", \"memberId\": 2}, \"category\": \"MILESTONE\",