INSERT INTO `AI_ARTICLE` (`ARTICLE_ID`, `CLUB_ID`, `SESSION_ID`, `MATCH_ID`, `ARTICLE_TYPE`, `TITLE`, `SUMMARY`, `CONTENT`, `MODEL_NAME`, `PROMPT_VERSION`, `INSIGHT_RULE_VERSION`, `STATUS`, `PUBLISHED_YN`, `PUBLISHED_AT`, `PARENT_ARTICLE_ID`, `GENERATION_NO`, `REQUEST_JSON`, `RESPONSE_JSON`, `ERROR_MESSAGE`, `UPDATED_AT`, `CREATED_AT`) VALUES (12,1,6,NULL,'PRE_MATCH','권태홍, 손원일 상대 1승 5패… 설욕할까','권태홍은 손원일 상대로 1승 5패. 오늘은 다른 팀으로 갈려 설욕을 노린다.','8월 8일 토요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 게스트 1명도 함께 뛴다.\n\nA팀은 권태홍, 김상균, 안휘진 등 7명, B팀은 김동근, 김현섭, 박영현 등 6명, C팀은 김병채, 김승준, 김응철 등 6명으로 꾸려졌다.\n\n권태홍은 손원일 상대로 1승 5패. 오늘은 다른 팀으로 갈려 설욕을 노린다. 8월 득점 경쟁이 뜨겁다. 이민선이 4골, 김상균이 3골로 1골 차다.\n\n안휘진(5주), 김동근(5주), 이채현(5주), 권태홍(4주)과 진선호(4주)가 연속 득점 행진을 이어가고 있다. 변현우는 임우철 상대로 1승 1무 6패. 오늘은 다른 팀으로 갈려 설욕을 노린다.\n\n팀 간 전력이 고르게 나뉘어 어느 팀도 쉽게 승리를 장담하기 어렵다. 김현섭과 윤영문은 같은 팀으로 12경기에서 3승에 그쳤다. 오늘은 징크스를 깰 수 있을까.\n\n경기 결과와 오늘의 주인공은 마감 기사에서 전한다.','sample-template','wire_prompt_v4','ATTENDANCE_STREAK:attendance_streak_v1,CLOSE_MATCH_EXPECTED:close_match_expected_v1,JINX_PAIR:jinx_pair_v1,MILESTONE_EXPECTED:milestone_expected_v1,NEMESIS_MATCH:nemesis_match_v1,RARE_PAIR:rare_pair_v1,SCORING_RACE:scoring_race_v1,SCORING_STREAK:scoring_streak_v1','PUBLISHED',1,'2026-08-07 22:46:00.000',NULL,1,'{\"teams\": [{\"members\": [\"권태홍\", \"김상균\", \"안휘진\", \"이용준\", \"임우철\", \"진선호\"], \"teamCode\": \"A\", \"guestCount\": 1}, {\"members\": [\"김동근\", \"김현섭\", \"박영현\", \"유창우\", \"윤영문\", \"이채현\"], \"teamCode\": \"B\", \"guestCount\": 0}, {\"members\": [\"김병채\", \"김승준\", \"김응철\", \"변현우\", \"손원일\", \"이민선\"], \"teamCode\": \"C\", \"guestCount\": 0}], \"clubName\": \"YPR\", \"insights\": [{\"id\": 141, \"type\": \"NEMESIS_MATCH\", \"facts\": {\"draws\": 0, \"rival\": {\"name\": \"손원일\", \"memberId\": 1}, \"member\": {\"name\": \"권태홍\", \"memberId\": 16}, \"members\": [{\"name\": \"권태홍\", \"memberId\": 16}, {\"name\": \"손원일\", \"memberId\": 1}], \"rivalWins\": 5, \"teamCount\": 3, \"lossStreak\": 0, \"memberWins\": 1, \"rivalTeamCode\": \"C\", \"me