INSERT INTO `AI_ARTICLE` (`ARTICLE_ID`, `CLUB_ID`, `SESSION_ID`, `MATCH_ID`, `ARTICLE_TYPE`, `TITLE`, `SUMMARY`, `CONTENT`, `MODEL_NAME`, `PROMPT_VERSION`, `INSIGHT_RULE_VERSION`, `STATUS`, `PUBLISHED_YN`, `PUBLISHED_AT`, `PARENT_ARTICLE_ID`, `GENERATION_NO`, `REQUEST_JSON`, `RESPONSE_JSON`, `ERROR_MESSAGE`, `UPDATED_AT`, `CREATED_AT`) VALUES (25,1,12,NULL,'PRE_MATCH','김응철·이채현, 다시 한 팀… 함께 11경기 8승','김응철과 이채현이 다시 한 팀이 됐다. 같은 팀으로 뛴 11경기에서 8승을 거둔 조합이다.','9월 19일 토요일, YPR 19명이 3개 팀으로 나뉘어 맞붙는다. 게스트 2명도 함께 뛴다.\n\nA팀은 권태홍, 김응철, 김현섭 등 7명, B팀은 김병채, 김상균, 박영현 등 6명, C팀은 김동근, 변현우, 안휘진 등 6명으로 꾸려졌다.\n\n김응철과 이채현이 다시 한 팀이 됐다. 같은 팀으로 뛴 11경기에서 8승을 거둔 조합이다. 안휘진(11주), 권태홍(8주), 손원일(7주), 김상균(7주)과 김현섭(6주)이 연속 득점 행진을 이어가고 있다.\n\n박영현은 이민선 상대로 0승 1무 5패. 최근 3연패 중이다. 오늘은 다른 팀으로 갈려 설욕을 노린다. 안휘진(12주), 김동근(12주)과 김병채(12주)가 개근 행진을 이어가고 있다.\n\n손원일, 유창우와 변현우는 나란히 4연승을 달리고 있다. 윤기창과 김동근은 같은 팀으로 11경기에서 2승에 그쳤다. 오늘은 징크스를 깰 수 있을까.\n\n누가 오늘의 주인공이 될지는 마감 기사에서 확인할 수 있다.','sample-template','wire_prompt_v4','ATTENDANCE_STREAK:attendance_streak_v1,CLOSE_MATCH_EXPECTED:close_match_expected_v1,DUO_REUNITED:duo_reunited_v1,JINX_PAIR:jinx_pair_v1,MILESTONE_EXPECTED:milestone_expected_v1,NEMESIS_MATCH:nemesis_match_v1,RARE_PAIR:rare_pair_v1,SCORING_RACE:scoring_race_v1,SCORING_STREAK:scoring_streak_v1,WIN_STREAK:win_streak_v1','PUBLISHED',1,'2026-09-18 22:46:00.000',NULL,1,'{\"teams\": [{\"members\": [\"권태홍\", \"김응철\", \"김현섭\", \"유창우\", \"이민선\", \"이채현\"], \"teamCode\": \"A\", \"guestCount\": 1}, {\"members\": [\"김병채\", \"김상균\", \"박영현\", \"손원일\", \"이용준\"], \"teamCode\": \"B\", \"guestCount\": 1}, {\"members\": [\"김동근\", \"변현우\", \"안휘진\", \"윤기창\", \"윤영문\", \"이종훈\"], \"teamCode\": \"C\", \"guestCount\": 0}], \"clubName\": \"YPR\", \"insights\": [{\"id\": 453, \"type\": \"SCORING_STREAK\", \"facts\": {\"member\": {\"name\": \"안휘진\", \"memberId\": 3}, \"streak\": 11, \"teamCode\": \"C\", \"streakUnit\": \"일정\"}, \"subject\": {\"name\": \"안휘진\", \"memberId\": 3}, \"category\": \"STREAK\", \"importance\": 90}, {\"id\": 467, \