INSERT INTO `AI_ARTICLE` (`ARTICLE_ID`, `CLUB_ID`, `SESSION_ID`, `MATCH_ID`, `ARTICLE_TYPE`, `TITLE`, `SUMMARY`, `CONTENT`, `MODEL_NAME`, `PROMPT_VERSION`, `INSIGHT_RULE_VERSION`, `STATUS`, `PUBLISHED_YN`, `PUBLISHED_AT`, `PARENT_ARTICLE_ID`, `GENERATION_NO`, `REQUEST_JSON`, `RESPONSE_JSON`, `ERROR_MESSAGE`, `UPDATED_AT`, `CREATED_AT`) VALUES (35,1,16,NULL,'SESSION_RECAP','김재홍, 김병채 상대 4연패 끊었다','김재홍은 오늘 김병채와의 맞대결에서 2승 1패로 앞서며 설욕에 성공했다.','10월 17일 YPR은 8경기를 치르며 총 24골을 기록했다. A팀이 3승 1무 2패로 가장 많은 승리를 챙겼다.\n\n득점 순위에서는 안휘진(3골), 권태홍(3골), 유창우(2골) 순으로 앞섰다.\n\n김재홍은 오늘 김병채와의 맞대결에서 2승 1패로 앞서며 설욕에 성공했다. 권태홍(13주), 김현섭(10주), 이채현(7주)과 전원재(4주)가 연속 골 행진을 이어갔다.\n\n김현섭, 윤기창과 구대현이 나란히 통산 50경기 출전 고지를 밟았다. 박영현이 통산 10골 고지를 밟았다.\n\n권태홍은 오늘 3골을 넣어 하루 최다 기록(2골)을 넘어섰다. 이용준은 오늘도 구대현 상대로 2승을 챙기며 강세를 이어갔다.\n\n1경기  A 2 : 1 B\n2경기  A 4 : 2 C\n3경기  C 2 : 1 B\n4경기  B 1 : 0 A\n5경기  A 2 : 0 C\n6경기  C 1 : 1 B\n7경기  B 2 : 1 A\n8경기  A 2 : 2 C','sample-template','wire_prompt_v4','MILESTONE_ACHIEVED:milestone_achieved_v1,PERSONAL_BEST_GOALS:personal_best_goals_v1,REVENGE_RESULT:revenge_result_v1,SCORING_STREAK:scoring_streak_v1,TITLE_AWARDED:title_awarded_v1','GENERATED',0,NULL,NULL,1,'{\"clubName\": \"YPR\", \"insights\": [{\"id\": 692, \"type\": \"SCORING_STREAK\", \"facts\": {\"member\": {\"name\": \"김현섭\", \"memberId\": 6}, \"streak\": 10, \"goalsToday\": 2, \"streakUnit\": \"일정\"}, \"subject\": {\"name\": \"김현섭\", \"memberId\": 6}, \"category\": \"STREAK\", \"importance\": 90}, {\"id\": 696, \"type\": \"SCORING_STREAK\", \"facts\": {\"member\": {\"name\": \"권태홍\", \"memberId\": 16}, \"streak\": 13, \"goalsToday\": 3, \"streakUnit\": \"일정\"}, \"subject\": {\"name\": \"권태홍\", \"memberId\": 16}, \"category\": \"STREAK\", \"importance\": 90}, {\"id\": 700, \"type\": \"REVENGE_RESULT\", \"facts\": {\"rival\": {\"name\": \"김병채\", \"memberId\": 23}, \"member\": {\"name\": \"김재홍\", \"memberId\": 13}, \"members\": [{\"name\": \"김재홍\", \"memberId\": 13}, {\"name\": \"김병채\", \"memberId\": 23}], \"outcome\": \"REVEN